int kvm_pit_read(struct kvm_io_device *this, gpa_t addr, int len, void *data)
{
    int ret = -EOPNOTSUPP;
    struct kvm_pit *pit = kvm_io_device_data(this);
    int channel;

    if (addr < 0x40 || addr > 0x43)
        goto out;

    channel = addr - 0x40;

    mutex_lock(&pit->mutex);

    switch (len) {
    case 1:
        switch (channel) {
        case 0:
        case 1:
            ret = 0;
            break;
        case 2:
            *(u8 *)data = pit->speaker_data;
            ret = 0;
            break;
        }
        break;
    case 2:
        switch (channel) {
        case 0:
        case 1:
            *(u16 *)data = pit->channels[channel].count;
            ret = 0;
            break;
        }
        break;
    }

    mutex_unlock(&pit->mutex);
out:
    return ret;
}

int kvm_pit_io_read(struct kvm_io_device *this, gpa_t addr, int len, void *data)
{
	struct kvm_pit *pit = this->data;
	int ret = -EOPNOTSUPP;
	unsigned int port = addr & 0xff;

	if (port >= KVM_PIT_BASE_ADDRESS && port <= KVM_PIT_MAX_ADDRESS) {
		unsigned char val = 0;
		mutex_lock(&pit->pit_state_mutex);

		switch (port) {
		case 0x40:
		case 0x41:
		case 0x42:
			/* Read from PIT channel */
			val = pit->channels[port - 0x40].counter;
			break;
		case 0x43:
			/* Read from PIT command register (readonly) */
			val = pit->channels[0].command;
			break;
		default:
			break;
		}

		mutex_unlock(&pit->pit_state_mutex);

		if (len == sizeof(val)) {
			memcpy(data, &val, len);
			ret = 0;
		}
	}

	return ret;
}

int kvm_pit_read(struct kvm_io_device *this, gpa_t addr, int len, void *data)
{
    int ret = -EOPNOTSUPP;

    if (addr < 0x40 || addr >= 0x48)
        return ret;

    mutex_lock(&pit_mutex);

    if (addr == 0x40) {
        /* Read channel 0 latch */
        *(u8 *)data = pit_state.channel0_latch;
        ret = len;
    } else if (addr == 0x41) {
        /* Read channel 1 latch */
        *(u8 *)data = pit_state.channel1_latch;
        ret = len;
    } else if (addr == 0x42) {
        /* Read channel 2 latch */
        *(u8 *)data = pit_state.channel2_latch;
        ret = len;
    } else if (addr == 0x43) {
        /* Read command/status register */
        *(u8 *)data = pit_state.command;
        ret = len;
    }

    mutex_unlock(&pit_mutex);

    return ret;
}

int kvm_pit_read(struct kvm_io_device *this, gpa_t addr, int len, void *data)
{
    struct kvm_pit *pit = kvm_io_device_data(this);
    int ret = -EOPNOTSUPP;

    if (addr < 0x40 || addr > 0x43)
        return ret;

    mutex_lock(&pit->pit_state_mutex);

    switch (addr) {
    case 0x40:
    case 0x41:
    case 0x42:
        /* Read from PIT channels 0, 1, or 2 */
        *(u8 *)data = pit_read_channel(pit, addr - 0x40);
        break;
    case 0x43:
        /* Read status register */
        *(u8 *)data = pit->status;
        break;
    default:
        break;
    }

    mutex_unlock(&pit->pit_state_mutex);
    return 0;
}

int kvm_pit_read(struct kvm_io_device *this, gpa_t addr, int len, void *data)
{
    int ret = -EOPNOTSUPP;

    if (addr >= 0x40 && addr <= 0x43) {
        struct kvm_pit *pit = kvm_io_device_data(this);
        unsigned long flags;
        u8 val = 0;

        spin_lock_irqsave(&pit->pit_state->lock, flags);

        switch (addr) {
        case 0x40:
            val = pit->pit_state->channel0_counter & 0xff;
            break;
        case 0x41:
            val = pit->pit_state->channel1_counter & 0xff;
            break;
        case 0x42:
            val = pit->pit_state->channel2_counter & 0xff;
            break;
        case 0x43:
            val = pit->pit_state->mode & 0xff;
            break;
        }

        spin_unlock_irqrestore(&pit->pit_state->lock, flags);

        if (len == 1)
            *(u8 *)data = val;
        else
            *(u16 *)data = val;

        ret = len;
    }

    return ret;
}
